def is_multiply_prime(a):
    """Write a function that returns true if the given number is the multiplication of 3 prime numbers
    and false otherwise.
    Knowing that (a) is less then 100. 
    Example:
    is_multiply_prime(30) == True
    30 = 2 * 3 * 5
    """
    def is_prime(n):
        if n <= 1:
            return False
        if n <= 3:
            return True
        if n % 2 == 0 or n % 3 == 0:
            return False
        i = 5
        while i * i <= n:
            if n % i == 0 or n % (i + 2) == 0:
                return False
            i += 6
        return True

    if a < 2:
        return False
    factors = []
    d = 2
    while d * d <= a:
        while a % d == 0:
            factors.append(d)
            a //= d
        d += 1 if d == 2 else 2
    if a > 1:
        factors.append(a)

    if len(factors) != 3 or any(not is_prime(f) for f in factors):
        return False
    return True
```

