def sumofFactors(n: int) -> int:
    """Return the sum of all even factors of n."""
    if n <= 0:
        return 0

    # Find all factors and sum those that are even
    total = 0
    i = 1
    while i * i <= n:
        remainder = n // i
        if n % i == 0:
            # Factor i
            if i % 2 == 0:
                total += i
            # If i != remainder, factor remainder
            if i != remainder and remainder % 2 == 0:
                total += remainder
        i += 1
    return total
```

