def iscube(a):
    import math
    if a == 0:
        return True
    # Determine integer root of absolute value
    root_approx = int(round(abs(a) ** (1/3)))
    root = root_approx
    # Adjust for floating point errors by checking nearby integers
    while root > 0 and root ** 3 > abs(a):
        root -= 1
    while root > 0 and root ** 3 < abs(a):
        root += 1
    return root ** 3 == abs(a)
```

