def is_undulating(n: int) -> bool:
    """
    Check if a number is undulating.
    A number is undulating if its digits alternate strictly between increasing and decreasing.
    Adjacent digits must not be equal.
    The pattern must be strictly alternating: up, down, up, down... OR down, up, down, up...
    """
    s = str(n)
    if len(s) <= 2:
        return False

    # Determine the first relation (between first and second digit)
    if int(s[1]) > int(s[0]):
        expected = 1  # going up
    elif int(s[1]) < int(s[0]):
        expected = -1 # going down
    else:
        return False  # equal adjacent digits are not allowed

    for i in range(1, len(s) - 1):
        curr = int(s[i])
        nxt = int(s[i+1])

        # Determine the relation between current and next
        if nxt > curr:
            actual = 1
        elif nxt < curr:
            actual = -1
        else:
            return False  # equal adjacent digits not allowed

        if actual != expected:
            return False

        expected = -expected  # flip expected direction

    return True
```

