def closest_integer(value):
    '''
    Create a function that takes a value (string) representing a number
    and returns the closest integer to it. If the number is equidistant
    from two integers, round it away from zero.

    Examples
    >>> closest_integer("10")
    10
    >>> closest_integer("15.3")
    15
    '''
    num = float(value)
    if num >= 0:
        # For positive numbers, round up if fractional part >= 0.5
        if num - int(num) >= 0.5:
            return int(num) + 1
        else:
            return int(num)
    else:
        # For negative numbers, round up (away from zero) if fractional part >= 0.5
        if -num - int(-num) >= 0.5:
            return int(num) - 1
        else:
            return int(num)
```

