def max_product(nums):
    if not nums:
        return 0

    n = len(nums)
    # dp_max[i] = maximum product of an increasing subsequence ending at index i
    # dp_min[i] = minimum product of an increasing subsequence ending at index i
    # We include both max and min because a small (possibly negative) number 
    # could become large when multiplied by another negative number.

    dp_min = list(nums)
    dp_max = list(nums)

    for i in range(1, n):
        if nums[i] > 0:
            # If current number is positive, extending any increasing subsequence ending at j < i with nums[j] < nums[i] is always beneficial
            candidates = []
            for j in range(i):
                if nums[j] < nums[i]:
                    candidates.append(dp_max[j] * nums[i])
                    candidates.append(dp_min[j] * nums[i])
            if candidates:
                dp_max[i] = max(candidates)
                dp_min[i] = min(candidates)
            else:
                dp_max[i] = nums[i]
                dp_min[i] = nums[i]
        else:
            # If current number is negative
            candidates = []
            for j in range(i):
                if nums[j] < nums[i]:
                    candidates.append(dp_max[j] * nums[i])
                    candidates.append(dp_min[j] * nums[i])
            if candidates:
                dp_max[i] = max(candidates)
                dp_min[i] = min(candidates)
            else:
                dp_max[i] = nums[i]
                dp_min[i] = nums[i]
        if nums[i] > 0:
            if dp_max[i] < nums[i]:
                dp_max[i] = nums[i]
            if dp_min[i] > nums[i]:
                dp_min[i] = nums[i]
        else:
            if dp_max[i] > nums[i]:
                dp_max[i] = nums[i]
            if dp_min[i] < nums[i]:
                dp_min[i] = nums[i]

    return max(dp_max)
```

