def dict_depth(d):
    """
    Calculate the maximum depth of a nested dictionary structure.

    Handles nested dictionaries, lists (including lists with dicts), and other types.
    - Depth of primitives (non-dict/list values) is 0.
    - Depth of an empty dict/list is 0 (but the container itself adds 1 if it's the root).
    - Depth increases by 1 for each level of nesting.

    Parameters:
        d (dict | any): The input dictionary (may contain nested dicts, lists, etc.).

    Returns:
        int: The maximum depth of the dictionary.
    """
    def calculate_depth_of_value(value, current_depth=0):
        if isinstance(value, dict):
            if not value:
                return current_depth
            max_child_depth = 0
            for v in value.values():
                child_depth = calculate_depth_of_value(v, current_depth + 1)
                max_child_depth = max(max_child_depth, child_depth)
            return max_child_depth
        elif isinstance(value, list):
            if not value:
                return current_depth
            max_child_depth = 0
            for item in value:
                child_depth = calculate_depth_of_value(item, current_depth + 1)
