        return True
    if a > 0:
        root_approx = int(round(a ** (1/3)))
    else:
        root_approx = int(round((-a) ** (1/3)))

    # Adjust to find the exact integer root
    # For positive numbers, we check around the approximation
    # For negative numbers, we also check around the approximation
    # Since we're dealing with integer cubes, we can check the absolute value
    # and then adjust the sign if needed

    if a > 0:
        root = root_approx
    else:
        root = -root_approx

    # Fine-tune to find the exact integer root
    while (root + 1) ** 3 <= abs(a):
        root += 1
    while root ** 3 > abs(a):
        root -= 1

    return root ** 3 == abs(a)
