            max_child_depth = 0
            for item in value:
                child_depth = calculate_depth_of_value(item, current_depth + 1)
                max_child_depth = max(max_child_depth, child_depth)
            return max_child_depth
        else:
            return current_depth

    if not isinstance(d, dict):
        return 0
    return calculate_depth_of_value(d, 0)
