def sort_array(arr):
    """
    Sorts an array of integers according to:
    1. Number of ones in their binary representation (ascending).
    2. For ties, by decimal value (ascending).

    Handles negative numbers by computing the bit count using two's complement
    logic (bit_count for Python 3.10+, or manual calculation for older versions).
    """
    def bit_count(n):
        # Handle Python versions with int.bit_count() (3.10+)
        if hasattr(int, "bit_count"):
            return n.bit_count()
        # Fallback for older Python versions using bin() with two's complement simulation
        # For negative numbers, we compute bit count as if in two's complement with sufficient width
        if n >= 0:
            return bin(n).count('1')
        else:
            # Use a fixed large bit width (e.g., 64-bit) to simulate two's complement
            width = 64
            two_complement = n + (1 << width)
            return bin(two_complement).count('1')

    return sorted(arr, key=lambda x: (bit_count(x), x))
