def dict_depth(d):
    """
    Calculate the maximum depth of a nested dictionary structure.

    Handles nested dictionaries, lists (including lists with dicts), and other types.
    - Depth of primitives (non-dict/list values) is 0.
    - Empty containers (dict or list) have depth 0.
    - Depth increases by 1 for each level of nesting.

    Parameters:
        d (dict | any): The input dictionary (may contain nested dicts, lists, etc.).

    Returns:
        int: The maximum depth of the dictionary.
    """
    def calculate_depth(value, current_depth):
        if isinstance(value, dict):
            if not value:
                return current_depth
            max_child_depth = 0
            for v in value.values():
                child_depth = calculate_depth(v, current_depth + 1)
                if child_depth > max_child_depth:
                    max_child_depth = child_depth
            return max_child_depth + 1
        elif isinstance(value, list):
            if not value:
                return current_depth
            max_child_depth = 0
            for item in value:
                child_depth = calculate_depth(item, current_depth + 1)
                if child_depth > max_child_depth:
                    max_child_depth = child_depth
            return max_child_depth + 1
        else:
            return current_depth

    if not isinstance(d, dict):
        return 0
    return calculate_depth(d, 0)
```

