def is_multiply_prime(a):
    """Return True if a is the product of exactly three prime numbers, False otherwise.
    Constraint: a < 100.
    Examples:
    is_multiply_prime(30) -> True  (2 * 3 * 5)
    is_multiply_prime(12) -> False (2 * 2 * 3)
    """
    def is_prime(n):
        if n <= 1:
            return False
        if n <= 3:
            return True
        if n % 2 == 0 or n % 3 == 0:
            return False
        i = 5
        while i * i <= n:
            if n % i == 0 or n % (i + 2) == 0:
                return False
            i += 6
        return True

    # Find all prime factors with multiplicity
    factors = []
    d = 2
    temp = a
    while d * d <= temp:
        while temp % d == 0:
            factors.append(d)
            temp //= d
        if d > 2:
            d += 1
        else:
            d += 2
    if temp > 1:
        factors.append(temp)

    # Check that there are exactly 3 factors (with multiplicity)
    if len(factors) != 3:
        return False

    # Check that every factor is prime
    if any(not is_prime(f) for f in factors):
        return False

    return True
