def max_product(nums):
    if not nums:
        return 0

    n = len(nums)
    # dp_max[i] = maximum product of an increasing subsequence ending at index i
    # dp_min[i] = minimum product of an increasing subsequence ending at index i
    dp_max = list(nums)
    dp_min = list(nums)

    for i in range(1, n):
        for j in range(i):
            if nums[j] < nums[i]:  # strictly increasing
                prod = nums[i]
                # Extend the best and worst sequences from j
                cand_max = dp_max[j] * prod
                cand_min = dp_min[j] * prod

                if nums[i] > 0:
                    if cand_max > dp_max[i]:
                        dp_max[i] = cand_max
                    if cand_min < dp_min[i]:
                        dp_min[i] = cand_min
                elif nums[i] < 0:
                    if cand_max > dp_max[i]:
                        dp_max[i] = cand_max
                    if cand_min < dp_min[i]:
                        dp_min[i] = cand_min
                else:  # nums[i] == 0
                    # With 0, the product becomes 0; we can also start a new subsequence at 0
                    if 0 > dp_max[i]:
                        dp_max[i] = 0
                    if 0 < dp_min[i]:
                        dp_min[i] = 0

    # The overall maximum product is the maximum over all subsequences ending anywhere
    overall_max = 0
    for i in range(n):
        if nums[i] > 0:
            overall_max = max(overall_max, dp_max[i])
        elif nums[i] < 0:
            # For negative numbers, the maximum could come from dp_max[i]
            overall_max = max(overall_max, dp_max[i])
        else:  # nums[i] == 0
            overall_max = max(overall_max, dp_max[i])

    return overall_max
```

