def sort_array(arr):
    """
    Sorts an array of integers according to:
    1. Number of ones in their binary representation (ascending).
    2. For ties, by absolute decimal value (ascending).
    3. For ties in absolute value, negative numbers appear before positive numbers
       (effectively descending order for the signed value, e.g., -6 before -5).
    """
    def bit_count(n):
        return bin(abs(n)).count('1')

    def sort_key(x):
        ones = bit_count(x)
        abs_val = abs(x)
        # For negative numbers, we want them to come before positive numbers when abs values are equal.
        # Since we sort ascending, we can use a negative sign for negative numbers.
        sign_order = -1 if x < 0 else 1
        return (ones, abs_val, sign_order)

    return sorted(arr, key=sort_key)
