def next_smallest_palindrome(n: int) -> int:
    """Return the next smallest palindrome strictly greater than n."""
    def is_palindrome(num: int) -> bool:
        s = str(num)
        return s == s[::-1]

    x = n + 1
    while not is_palindrome(x):
        # If we've wrapped around (e.g., from 999 to next integer with more digits),
        # force a jump to the smallest palindrome of the next length.
        s = str(x)
        length = len(s)
        if x < 0:
            raise ValueError("Input must be non-negative")
        # Find the smallest palindrome greater than x by constructing from the next length
        next_len = length + 1
        if next_len == 1:
            # smallest 1-digit palindrome > x (only possible if x >= 9, which we handle above)
            continue

        # Smallest palindrome of length `next_len`:
        first_half = [1] + [0] * (next_len // 2 - 1)
        if next_len % 2 == 1:
            first_half[-1] = 0  # middle digit
        else:
            pass  # even length, last digit of first half is the mirror start
        candidate = int("".join(str(d) for d in first_half)) + int("".join(str(d) for d in first_half[-2::-1]))
        if candidate <= x:
            candidate = int("".join(str(d) for d in first_half) + str(first_half[-1]) + "".join(str(d) for d in first_half[-2::-1]))

        # Fallback: brute force from x up to 10^length
        while not is_palindrome(x):
            if x < 10**length:
                x += 1
            else:
                # Should not happen if we handle length increment, but as safety:
                break

    while not is_palindrome(x):
        x += 1

    return x
```

