def max_product(nums):
    if not nums:
        return 0

    n = len(nums)
    dp_max = list(nums)
    dp_min = list(nums)

    for i in range(1, n):
        for j in range(i):
            if nums[j] < nums[i]:  # strictly increasing
                cand_max = dp_max[j] * nums[i]
                cand_min = dp_min[j] * nums[i]

                if cand_max > dp_max[i]:
                    dp_max[i] = cand_max
                if cand_min < dp_min[i]:
                    dp_min[i] = cand_min

    # Consider subsequences of length 1 as well
    overall_max = float('-inf')
    for x in nums:
        overall_max = max(overall_max, x)

    for i in range(n):
        overall_max = max(overall_max, dp_max[i], dp_min[i])

    return overall_max
