def is_majority(arr, n, element):
    if n == 0:
        return False
    # In a sorted array, if element is the majority, it must appear around the middle.
    # We find the first and last occurrence of element using binary search.
    def find_first(arr, target):
        lo, hi = 0, n - 1
        result = n
        while lo <= hi:
            mid = (lo + hi) // 2
            if arr[mid] == target:
                result = mid
                hi = mid - 1
            elif arr[mid] < target:
                lo = mid + 1
            else:
                hi = mid - 1
        return result

    def find_last(arr, target):
        lo, hi = 0, n - 1
        result = -1
        while lo <= hi:
            mid = (lo + hi) // 2
            if arr[mid] == target:
                result = mid
                lo = mid + 1
            elif arr[mid] < target:
                lo = mid + 1
            else:
                hi = mid - 1
        return result

    first = find_first(arr, element)
    last = find_last(arr, element)

    if first == n or last == -1:
        return False
    count = last - first + 1
    return count > n // 2
```

