def dict_depth(d):
    """
    Calculate the maximum depth of a nested dictionary structure.

    Handles nested dictionaries, lists, and None values.
    - Depth of primitives (including None, str, int, etc.) is 0.
    - Empty containers (dict or list) have depth 0.
    - Depth increases by 1 for each level of nesting.
    - If the input is not a dictionary, returns 0.

    Parameters:
        d: The input value (must be a dictionary, or handled gracefully).

    Returns:
        int: The maximum depth of the dictionary.
    """
    def calculate_depth(value, current_depth):
        if isinstance(value, dict):
            if not value:  # Empty dict
                return current_depth
            return max(calculate_depth(v, current_depth + 1) for v in value.values())
        elif isinstance(value, list):
            if not value:  # Empty list
                return current_depth
            return max(calculate_depth(item, current_depth + 1) for item in value)
        else:
            # Primitives (including None, str, int, etc.) do not increase depth
            return current_depth

    if not isinstance(d, dict):
        return 0

    return calculate_depth(d, 0)
```

