def max_product(nums):
    if not nums:
        return None

    n = len(nums)
    dp_max = [float('-inf')] * n
    dp_min = [float('inf')] * n

    for i in range(n):
        if i == 0:
            dp_max[i] = nums[i]
            dp_min[i] = nums[i]
            continue

        # Start with the element itself as a candidate subsequence
        curr_max = nums[i]
        curr_min = nums[i]

        for j in range(i):
            if nums[j] < nums[i]:
                # Extend subsequences ending at j
                cand_max = dp_max[j] * nums[i]
                cand_min = dp_min[j] * nums[i]

                if cand_max > curr_max:
                    curr_max = cand_max
                if cand_min < curr_min:
                    curr_min = cand_min

        dp_max[i] = curr_max
        dp_min[i] = curr_min

    overall_max = float('-inf')
    for x in nums:
        if x > overall_max:
            overall_max = x
    for v in dp_max:
        if v > overall_max:
            overall_max = v
    for v in dp_min:
        if v > overall_max:
            overall_max = v

    return overall_max
```

