def sumofFactors(n: int) -> int:
    """Return the sum of all even factors of n."""
    if n <= 0:
        return 0
    total = 0
    i = 1
    while i * i <= n:
        if n % i == 0:
            if i % 2 == 0:
                total += i
            remainder = n // i
            if remainder != i and remainder % 2 == 0:
                total += remainder
        i += 1
    return total
```

