def dict_depth(d):
    """
    Calculate the maximum depth of a nested dictionary structure.

    Depth definition:
    - Primitives (including None, str, int, etc.) have depth 0.
    - Empty containers (dict or list) have depth 0.
    - Non-empty containers increase depth by 1, then recursively add the maximum depth of their contents.

    Parameters:
        d: The input value.

    Returns:
        int: The maximum depth of the dictionary.
    """
    def calculate_depth(value):
        if isinstance(value, dict):
            return 1 + max((calculate_depth(v) for v in value.values()), default=0)
        elif isinstance(value, list):
            return 1 + max((calculate_depth(item) for item in value), default=0)
        else:
            # Primitives and None return 0
            return 0

    if not isinstance(d, dict):
        return 0

    return calculate_depth(d)
```

